import { Component, OnInit, OnDestroy } from '@angular/core';
import { Router } from '@angular/router';
import { ApiService } from '../../services/api.service';

export interface Shape {
  id: string;
  name: string;
  symbol: string;
  color: string;
  bgColor: string;
  placed: boolean;
  isCorrect?: boolean;
}

export interface DropZone {
  id: string;
  targetShapeId: string;
  shape: Shape | null;
  label: string;
  hint: string;
  isCorrect: boolean;
  isWrong: boolean;
}

@Component({
  selector: 'app-shape-puzzle',
  templateUrl: './shape-puzzle.component.html',
  styleUrls: ['./shape-puzzle.component.css']
})
export class ShapePuzzleComponent implements OnInit, OnDestroy {
  allShapes: Shape[] = [
    { id: 'circle', name: 'Circle', symbol: '⭕', color: '#FF6B6B', bgColor: '#ffe0e0', placed: false },
    { id: 'triangle', name: 'Triangle', symbol: '🔺', color: '#FF8C00', bgColor: '#fff0d9', placed: false },
    { id: 'square', name: 'Square', symbol: '⬛', color: '#333', bgColor: '#f0f0f0', placed: false },
    { id: 'star', name: 'Star', symbol: '⭐', color: '#FFD700', bgColor: '#fffbe0', placed: false },
    { id: 'heart', name: 'Heart', symbol: '❤️', color: '#E91E63', bgColor: '#fce4ec', placed: false },
    { id: 'diamond', name: 'Diamond', symbol: '💎', color: '#00BCD4', bgColor: '#e0f7fa', placed: false },
    { id: 'moon', name: 'Moon', symbol: '🌙', color: '#9C27B0', bgColor: '#f3e5f5', placed: false },
    { id: 'sun', name: 'Sun', symbol: '☀️', color: '#FF9800', bgColor: '#fff3e0', placed: false },
    { id: 'flower', name: 'Flower', symbol: '🌸', color: '#E91E63', bgColor: '#fce4ec', placed: false },
    { id: 'lightning', name: 'Lightning', symbol: '⚡', color: '#FFC107', bgColor: '#fffde7', placed: false },
  ];

  shapes: Shape[] = [];
  dropZones: DropZone[] = [];
  draggedShape: Shape | null = null;
  score = 0;
  moves = 0;
  level = 1;
  timer = 0;
  timerInterval: any;
  gameWon = false;
  gameStarted = false;
  playerName = '';
  showNameInput = true;
  correctCount = 0;
  scoreMessage = '';
  showHints = true;

  constructor(private router: Router, private apiService: ApiService) {}

  ngOnInit() {}
  ngOnDestroy() { this.clearTimer(); }

  startGame() {
    if (!this.playerName.trim()) { alert('Please enter your name!'); return; }
    this.showNameInput = false;
    this.initGame();
  }

  initGame() {
    this.score = 0; this.moves = 0; this.correctCount = 0;
    this.timer = 0; this.gameWon = false; this.draggedShape = null;
    this.scoreMessage = '';

    const count = this.level === 1 ? 4 : this.level === 2 ? 6 : 8;
    const selected = [...this.allShapes]
      .sort(() => Math.random() - 0.5)
      .slice(0, count)
      .map(s => ({ ...s, placed: false }));

    this.shapes = [...selected].sort(() => Math.random() - 0.5);

    this.dropZones = selected.map(shape => ({
      id: `zone-${shape.id}`,
      targetShapeId: shape.id,
      shape: null,
      label: shape.name,
      hint: shape.symbol,
      isCorrect: false,
      isWrong: false
    })).sort(() => Math.random() - 0.5);

    this.gameStarted = true;
    this.startTimer();
  }

  // Drag & Drop
  onDragStart(shape: Shape) {
    if (shape.placed) return;
    this.draggedShape = shape;
  }

  onDragOver(event: DragEvent) {
    event.preventDefault();
  }

  onDrop(event: DragEvent, zone: DropZone) {
    event.preventDefault();
    if (!this.draggedShape || zone.shape !== null) return;
    this.placeShape(this.draggedShape, zone);
    this.draggedShape = null;
  }

  // Click-to-place fallback
  selectShape(shape: Shape) {
    if (shape.placed) return;
    if (this.draggedShape?.id === shape.id) {
      this.draggedShape = null;
    } else {
      this.draggedShape = shape;
    }
  }

  clickZone(zone: DropZone) {
    if (this.draggedShape && !zone.shape) {
      this.placeShape(this.draggedShape, zone);
      this.draggedShape = null;
    } else if (zone.shape && !zone.isCorrect) {
      // Remove shape from zone
      const shape = this.shapes.find(s => s.id === zone.shape!.id);
      if (shape) shape.placed = false;
      zone.shape = null;
      zone.isWrong = false;
    }
  }

  placeShape(shape: Shape, zone: DropZone) {
    this.moves++;
    zone.shape = shape;
    shape.placed = true;
    zone.isWrong = false;

    if (shape.id === zone.targetShapeId) {
      zone.isCorrect = true;
      this.correctCount++;
      this.score += Math.max(5, 20 - this.moves);
      if (this.correctCount === this.dropZones.length) {
        this.handleWin();
      }
    } else {
      zone.isWrong = true;
      this.score = Math.max(0, this.score - 3);
      setTimeout(() => {
        if (zone.isWrong) {
          shape.placed = false;
          zone.shape = null;
          zone.isWrong = false;
        }
      }, 800);
    }
  }

  handleWin() {
    this.clearTimer();
    this.gameWon = true;
    const timeBonus = Math.max(0, 120 - this.timer);
    this.score += timeBonus;
    this.scoreMessage = `⚡ Speed bonus: +${timeBonus} pts!`;

    this.apiService.saveScore({
      playerName: this.playerName,
      gameType: 'shape-puzzle',
      score: this.score,
      level: this.level,
      timeTaken: this.timer
    }).subscribe({ error: () => {} });
  }

  nextLevel() {
    this.level = Math.min(this.level + 1, 3);
    this.initGame();
  }

  startTimer() {
    this.clearTimer();
    this.timerInterval = setInterval(() => this.timer++, 1000);
  }

  clearTimer() {
    if (this.timerInterval) clearInterval(this.timerInterval);
  }

  formatTime(s: number): string {
    return `${Math.floor(s / 60).toString().padStart(2,'0')}:${(s % 60).toString().padStart(2,'0')}`;
  }

  get availableShapes(): Shape[] {
    return this.shapes.filter(s => !s.placed);
  }

  goHome() { this.router.navigate(['/']); }
}
<!-- Name Input Screen -->
<div class="game-container" *ngIf="showNameInput">
  <div class="name-screen">
    <button class="back-btn" (click)="goHome()">← Back</button>
    <div class="title-area">
      <div class="big-emoji">🧩</div>
      <h1>Shape Puzzle!</h1>
      <p>Drag shapes into the right spots!</p>
    </div>

    <div class="options-panel">
      <h3>Level:</h3>
      <div class="mode-buttons">
        <button [class.active]="level === 1" (click)="level = 1">⭐ Easy (4 shapes)</button>
        <button [class.active]="level === 2" (click)="level = 2">⭐⭐ Medium (6 shapes)</button>
        <button [class.active]="level === 3" (click)="level = 3">⭐⭐⭐ Hard (8 shapes)</button>
      </div>
      <div class="hints-toggle">
        <label>
          <input type="checkbox" [(ngModel)]="showHints"> Show shape hints in zones
        </label>
      </div>
    </div>

    <div class="name-input-area">
      <label>Your Name:</label>
      <input type="text" [(ngModel)]="playerName" placeholder="Enter your name..." maxlength="20" (keyup.enter)="startGame()">
      <button class="start-btn" (click)="startGame()">🎮 Start Game!</button>
    </div>
  </div>
</div>

<!-- Game Screen -->
<div class="game-container" *ngIf="gameStarted && !showNameInput">
  <div class="game-header">
    <button class="back-btn" (click)="goHome()">← Home</button>
    <div class="stats">
      <span class="stat">⏱️ {{formatTime(timer)}}</span>
      <span class="stat">✅ {{correctCount}}/{{dropZones.length}}</span>
      <span class="stat">🌟 {{score}} pts</span>
      <span class="stat">🔄 {{moves}} moves</span>
    </div>
    <span class="level-badge">Level {{level}}</span>
  </div>

  <div class="instructions">
    <span *ngIf="!draggedShape">👆 Click a shape, then click a zone — or drag & drop!</span>
    <span *ngIf="draggedShape" class="dragging-hint">🎯 Now click the matching zone for <strong>{{draggedShape.name}}</strong>!</span>
  </div>

  <!-- Drop Zones -->
  <div class="drop-zones-area">
    <h3>Drop Zones</h3>
    <div class="drop-zones-grid">
      <div
        *ngFor="let zone of dropZones"
        class="drop-zone"
        [class.filled]="zone.shape !== null"
        [class.correct]="zone.isCorrect"
        [class.wrong]="zone.isWrong"
        [class.ready]="draggedShape !== null && zone.shape === null && !zone.isCorrect"
        (dragover)="onDragOver($event)"
        (drop)="onDrop($event, zone)"
        (click)="clickZone(zone)">
        <div class="zone-label">{{zone.label}}</div>
        <div class="zone-content" *ngIf="!zone.shape">
          <span class="zone-hint" *ngIf="showHints">{{zone.hint}}</span>
          <span class="zone-hint" *ngIf="!showHints">?</span>
        </div>
        <div class="zone-placed" *ngIf="zone.shape">
          <span class="shape-symbol">{{zone.shape.symbol}}</span>
          <span class="match-icon" *ngIf="zone.isCorrect">✅</span>
          <span class="match-icon" *ngIf="zone.isWrong">❌</span>
        </div>
      </div>
    </div>
  </div>

  <!-- Shapes Tray -->
  <div class="shapes-tray">
    <h3>Shapes Tray</h3>
    <div class="shapes-row">
      <div
        *ngFor="let shape of availableShapes"
        class="shape-tile"
        [class.selected]="draggedShape?.id === shape.id"
        [style.borderColor]="shape.color"
        [style.backgroundColor]="shape.bgColor"
        draggable="true"
        (dragstart)="onDragStart(shape)"
        (click)="selectShape(shape)">
        <span class="shape-emoji">{{shape.symbol}}</span>
        <span class="shape-name">{{shape.name}}</span>
      </div>
      <div class="empty-tray" *ngIf="availableShapes.length === 0 && !gameWon">
        🎉 All shapes placed!
      </div>
    </div>
  </div>

  <!-- Win Overlay -->
  <div class="win-overlay" *ngIf="gameWon">
    <div class="win-card">
      <div class="win-emoji">🏆</div>
      <h2>Puzzle Complete, {{playerName}}!</h2>
      <p>{{scoreMessage}}</p>
      <div class="win-stats">
        <div class="win-stat"><span>⭐ Score</span><strong>{{score}}</strong></div>
        <div class="win-stat"><span>⏱️ Time</span><strong>{{formatTime(timer)}}</strong></div>
        <div class="win-stat"><span>🔄 Moves</span><strong>{{moves}}</strong></div>
      </div>
      <div class="win-actions">
        <button (click)="nextLevel()" *ngIf="level < 3">🚀 Next Level!</button>
        <button (click)="initGame()">🔄 Play Again</button>
        <button class="home-btn" (click)="goHome()">🏠 Home</button>
      </div>
    </div>
  </div>
</div>
